CREATE DATABASE IF NOT EXISTS biblioteca_tp CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE biblioteca_tp;
CREATE TABLE CIUDAD (ID_CIUDAD INT PRIMARY KEY, NOMBRE VARCHAR(100) NOT NULL);
CREATE TABLE CAMPUS (ID_CAMPUS INT PRIMARY KEY, NOMBRE VARCHAR(100) NOT NULL, ID_CIUDAD INT NOT NULL, FOREIGN KEY (ID_CIUDAD) REFERENCES CIUDAD(ID_CIUDAD));
CREATE TABLE CARRERAS (ID_CARRERA INT PRIMARY KEY, NOMBRE VARCHAR(100) NOT NULL, ID_CAMPUS INT NOT NULL, FOREIGN KEY (ID_CAMPUS) REFERENCES CAMPUS(ID_CAMPUS));
CREATE TABLE ESTUDIANTES (RUT_EST VARCHAR(20) PRIMARY KEY, NOMBRES VARCHAR(100) NOT NULL, APELLIDOS VARCHAR(100) NOT NULL, EDAD INT NOT NULL, FONO VARCHAR(30), DIRECCION VARCHAR(200), ID_CARRERA INT NOT NULL, FOREIGN KEY (ID_CARRERA) REFERENCES CARRERAS(ID_CARRERA));
CREATE TABLE FUNCIONARIOS (RUT_FUNC VARCHAR(20) PRIMARY KEY, NOMBRES VARCHAR(100) NOT NULL, APELLIDOS VARCHAR(100) NOT NULL, EDAD INT NOT NULL, DIRECCION VARCHAR(200), SALUD VARCHAR(30) NOT NULL, ID_CAMPUS INT NOT NULL, FOREIGN KEY (ID_CAMPUS) REFERENCES CAMPUS(ID_CAMPUS));
CREATE TABLE AUTORES (RUT_AUTOR VARCHAR(20) PRIMARY KEY, NOMBRES VARCHAR(100) NOT NULL, APELLIDOS VARCHAR(100) NOT NULL);
CREATE TABLE EDITORIALES (ID_EDIT INT PRIMARY KEY, NOMBRE VARCHAR(100) NOT NULL, PAIS VARCHAR(100) NOT NULL);
CREATE TABLE TIPO (ID_TIPO INT PRIMARY KEY, TIPO_P VARCHAR(100) NOT NULL);
CREATE TABLE BIBLIOTECA (ID_BIBLIO INT PRIMARY KEY, BIBLIOTECA VARCHAR(100) NOT NULL);
CREATE TABLE LIBROS (COD_LIBRO INT PRIMARY KEY, TITULO VARCHAR(200) NOT NULL, ANIO INT NOT NULL, ID_BIBLIO INT NOT NULL, ID_TIPO INT NOT NULL, RUT_AUTOR VARCHAR(20) NOT NULL, ID_EDIT INT NOT NULL, FOREIGN KEY (ID_BIBLIO) REFERENCES BIBLIOTECA(ID_BIBLIO), FOREIGN KEY (ID_TIPO) REFERENCES TIPO(ID_TIPO), FOREIGN KEY (RUT_AUTOR) REFERENCES AUTORES(RUT_AUTOR), FOREIGN KEY (ID_EDIT) REFERENCES EDITORIALES(ID_EDIT));
-- PK compuesta exactamente como el diagrama: no permite repetir la misma terna.
CREATE TABLE PRESTAMO (RUT_EST VARCHAR(20) NOT NULL, RUT_FUNC VARCHAR(20) NOT NULL, COD_LIBRO INT NOT NULL, FECHA_P DATE NOT NULL, FECHA_E DATE NULL, PRIMARY KEY (RUT_EST,RUT_FUNC,COD_LIBRO), FOREIGN KEY (RUT_EST) REFERENCES ESTUDIANTES(RUT_EST), FOREIGN KEY (RUT_FUNC) REFERENCES FUNCIONARIOS(RUT_FUNC), FOREIGN KEY (COD_LIBRO) REFERENCES LIBROS(COD_LIBRO));
